public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (java.util.Arrays.equals(start, end)) return "can be travelled";
    java.util.Map<String, java.util.List<String>> adj = new java.util.HashMap<>();
    for (int[] p : paths) {
        if (p.length != 2 * n) continue;
        String a = java.util.Arrays.toString(java.util.Arrays.copyOfRange(p, 0, n));
        String b = java.util.Arrays.toString(java.util.Arrays.copyOfRange(p, n, 2 * n));
        adj.computeIfAbsent(a, k -> new java.util.ArrayList<>()).add(b);
        adj.computeIfAbsent(b, k -> new java.util.ArrayList<>()).add(a);
    }
    String startKey = java.util.Arrays.toString(start);
    String endKey = java.util.Arrays.toString(end);
    if (!adj.containsKey(startKey) || !adj.containsKey(endKey)) {
        return "cannot be travelled";
    }
    java.util.Set<String> visited = new java.util.HashSet<>();
    java.util.Deque<String> queue = new java.util.ArrayDeque<>();
    queue.add(startKey);
    visited.add(startKey);
    while (!queue.isEmpty()) {
        String cur = queue.poll();
        if (cur.equals(endKey)) return "can be travelled";
        for (String nb : adj.getOrDefault(cur, java.util.Collections.emptyList())) {
            if (!visited.contains(nb)) {
                visited.add(nb);
                queue.add(nb);
            }
        }
    }
    return "cannot be travelled";
}

