public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0) return false;
    int[] freq = new int[k];
    for (int num : arr) {
        int rem = ((num % k) + k) % k;
        freq[rem]++;
    }
    // Remainder 0 must have even count
    if (freq[0] % 2 != 0) return false;
    // If k is even, remainder k/2 must also have even count
    if (k % 2 == 0) {
        if (freq[k / 2] % 2 != 0) return false;
    }
    // Check other remainders
    for (int r = 1; r < k / 2; r++) {
        if (freq[r] != freq[k - r]) return false;
    }
    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    List<Integer>[] graph = new ArrayList[n];
    for (int i = 0; i < n; i++) {
        graph[i] = new ArrayList<>();
    }
    for (int[] edge : edges) {
        int u = edge[0];
        int v = edge[1];
        graph[u].add(v);
        graph[v].add(u);
    }
    int[] time = new int[1];
    dfs(0, -1, graph, hasApple, time);
    return time[0];
}

private boolean dfs(int node, int parent, List<Integer>[] graph, boolean[] hasApple, int[] time) {
    boolean has = hasApple[node];
    for (int neighbor : graph[node]) {
        if (neighbor == parent) continue;
        boolean childHas = dfs(neighbor, node, graph, hasApple, time);
        if (childHas) {
            time[0] += 2;
            has = true;
        }
    }
    return has;
}

public String sortString(String s) {
    int[] freq = new int[26];
    for (char c : s.toCharArray()) {
        freq[c - 'a']++;
    }
    StringBuilder sb = new StringBuilder();
    int total = s.length();
    while (sb.length() < total) {
        for (int i = 0; i < 26; i++) {
            if (freq[i] > 0) {
                sb.append((char) (i + 'a'));
                freq[i]--;
            }
        }
        for (int i = 25; i >= 0; i--) {
            if (freq[i] > 0) {
                sb.append((char) (i + 'a'));
                freq[i]--;
            }
        }
    }
    return sb.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;
    int totalSum = 0;
    for (int num : nums) totalSum += num;
    int maxK = n / 2;
    java.util.HashSet<Integer>[] dp = new java.util.HashSet[maxK + 1];
    for (int k = 0; k <= maxK; k++) dp[k] = new java.util.HashSet<>();
    dp[0].add(0);
    for (int num : nums) {
        for (int k = maxK; k >= 1; k--) {
            if (dp[k - 1].isEmpty()) continue;
            for (int prevSum : dp[k - 1]) {
                dp[k].add(prevSum + num);
            }
        }
    }
    for (int k = 1; k <= maxK; k++) {
        if ((totalSum * k) % n != 0) continue;
        int target = (totalSum * k) / n;
        if (dp[k].contains(target)) return true;
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return cost[0];
    int prev2 = cost[0];
    int prev1 = cost[1];
    for (int i = 2; i < n; i++) {
        int curr = cost[i] + Math.min(prev1, prev2);
        prev2 = prev1;
        prev1 = curr;
    }
    return Math.min(prev1, prev2);
}

