private int dfs(String s, int index, java.util.Set<String> seen) {
    if (index == s.length()) {
        return 0;
    }
    int max = 0;
    for (int end = index + 1; end <= s.length(); end++) {
        String sub = s.substring(index, end);
        if (!seen.contains(sub)) {
            seen.add(sub);
            int res = 1 + dfs(s, end, seen);
            if (res > max) {
                max = res;
            }
            seen.remove(sub);
        }
    }
    return max;
}

