public static int singleNumber(int[] nums) {
    int[] bitCount = new int[32];
    for (int num : nums) {
        for (int i = 0; i < 32; i++) {
            bitCount[i] += (num >> i) & 1;
        }
    }
    int result = 0;
    for (int i = 0; i < 32; i++) {
        if ((bitCount[i] % 3) != 0) {
            result |= (1 << i);
        }
    }
    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low == 0) {
        result.add(0);
    }
    ArrayDeque<Long> queue = new ArrayDeque<>();
    for (int d = 1; d <= 9; d++) {
        queue.offer((long) d);
    }
    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (num > high) {
            continue;
        }
        if (num >= low) {
            result.add((int) num);
        }
        int lastDigit = (int) (num % 10);
        if (lastDigit > 0) {
            long next = num * 10 + (lastDigit - 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
        if (lastDigit < 9) {
            long next = num * 10 + (lastDigit + 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
    }
    Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    if (n < 0) return 0;
    long count = 0;
    long factor = 1;
    while (n / factor != 0) {
        long lower = n % factor;
        long cur = (n / factor) % 10;
        long higher = n / (factor * 10);
        count += higher * factor;
        if (cur == 1) {
            count += lower + 1;
        } else if (cur > 1) {
            count += factor;
        }
        factor *= 10;
    }
    return (int) count;
}

