    return sb.reverse().toString();
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    // Precompute perfect squares up to 2000 (assuming A[i] <= 1000)
    java.util.HashSet<Integer> squares = new java.util.HashSet<>();
    for (int i = 0; i * i <= 2000; i++) {
        squares.add(i * i);
    }
    java.util.Map<Long, Integer> memo = new java.util.HashMap<>();
    int allMask = (1 << n) - 1;

    java.util.function.IntUnaryOperator dfs = new java.util.function.IntUnaryOperator() {
        @Override
        public int applyAsInt(int state) {
            int mask = state & 0xFFFFF; // lower bits for mask
            int last = (state >> 20) & 0xFFFFF; // next bits for last index, -1 encoded as 0xFFFFF
            long key = ((long)mask << 32) | (last & 0xFFFFFFFFL);
            if (memo.containsKey(key)) return memo.get(key);
            if (mask == allMask) {
                memo.put(key, 1);
                return 1;
            }
            int count = 0;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) == 0) {
                    if (last == -1 || squares.contains(A[last] + A[i])) {
                        int newMask = mask | (1 << i);
                        int newLast = i;
                        int newState = newMask | (newLast << 20);
                        count += dfs.applyAsInt(newState);
                    }
                }
            }
            memo.put(key, count);
            return count;
        }
    };

    // Start with mask 0 and last index -1 (encoded as 0xFFFFF)
    int startState = 0 | ((-1 & 0xFFFFF) << 20);
    return dfs.applyAsInt(startState);
}

