                        int newMask = mask | (1 << i);
                        int newLast = i;
                        int newState = newMask | (newLast << 20);
                        count += dfs.applyAsInt(newState);
                    }
                }
            }
            memo.put(key, count);
            return count;
        }

public static int largestRectangleArea(int[] heights) {
    int n = heights.length;
    int maxArea = 0;
    java.util.Deque<Integer> stack = new java.util.ArrayDeque<>();
    for (int i = 0; i <= n; i++) {
        int currentHeight = (i == n) ? 0 : heights[i];
        while (!stack.isEmpty() && currentHeight < heights[stack.peek()]) {
            int height = heights[stack.pop()];
            int width = stack.isEmpty() ? i : i - stack.peek() - 1;
            int area = height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack.push(i);
    }
    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int index = 0;
    int totalDiagonals = m + n - 1;
    for (int k = 0; k < totalDiagonals; k++) {
        if (k % 2 == 0) {
            int i = Math.min(k, m - 1);
            int j = k - i;
            while (i >= 0 && j < n) {
                result[index++] = mat[i][j];
                i--;
                j++;
            }
        } else {
            int j = Math.min(k, n - 1);
            int i = k - j;
            while (j >= 0 && i < m) {
                result[index++] = mat[i][j];
                i++;
                j--;
            }
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();
    int i = digits.length - 1;
    while (i > 0 && digits[i - 1] >= digits[i]) {
        i--;
    }
    if (i <= 0) {
        return -1;
    }
    int j = digits.length - 1;
    while (digits[j] <= digits[i - 1]) {
        j--;
    }
    char temp = digits[i - 1];
    digits[i - 1] = digits[j];
    digits[j] = temp;
    int left = i, right = digits.length - 1;
    while (left < right) {
        char t = digits[left];
        digits[left] = digits[right];
        digits[right] = t;
        left++;
        right--;
    }
    return Integer.parseInt(new String(digits));
}

