private static List<String> build(int cur, int total) {
    List<String> res = new ArrayList<>();
    if (cur == 0) {
        res.add("");
        return res;
    }
    if (cur == 1) {
        res.add("0");
        res.add("1");
        res.add("8");
        return res;
    }
    List<String> inner = build(cur - 2, total);
    for (String s : inner) {
        if (cur != total) {
            res.add("0" + s + "0");
        }
        res.add("1" + s + "1");
        res.add("6" + s + "9");
        res.add("8" + s + "8");
        res.add("9" + s + "6");
    }
    return res;
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    // Check for duplicate points
    for (int i = 0; i < 3; i++) {
        for (int j = i + 1; j < 3; j++) {
            if (points[i][0] == points[j][0] && points[i][1] == points[j][1]) {
                return false;
            }
        }
    }
    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];
    // Compute twice the area of the triangle (shoelace formula)
    int area2 = x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2);
    return area2 != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] ugly = new int[n];
    ugly[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    int next2 = 2, next3 = 3, next5 = 5;
    for (int i = 1; i < n; i++) {
        int nextUgly = Math.min(next2, Math.min(next3, next5));
        ugly[i] = nextUgly;
        if (nextUgly == next2) {
            i2++;
            next2 = ugly[i2] * 2;
        }
        if (nextUgly == next3) {
            i3++;
            next3 = ugly[i3] * 3;
        }
        if (nextUgly == next5) {
            i5++;
            next5 = ugly[i5] * 5;
        }
    }
    return ugly[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int maxLen = 1;
    int currentLen = 1;
    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            currentLen++;
        } else {
            if (currentLen > maxLen) {
                maxLen = currentLen;
            }
            currentLen = 1;
        }
    }
    if (currentLen > maxLen) {
        maxLen = currentLen;
    }
    return maxLen;
}

public static java.util.List<Integer> lexicalOrder(int n) {
    java.util.List<Integer> res = new java.util.ArrayList<>();
    int curr = 1;
    for (int i = 0; i < n; i++) {
        res.add(curr);
        if (curr * 10 <= n) {
            curr *= 10;
        } else {
            if (curr % 10 != 9 && curr + 1 <= n) {
                curr++;
            } else {
                while ((curr / 10) % 10 == 9 || curr + 1 > n) {
                    curr /= 10;
                }
                curr++;
            }
        }
    }
    return res;
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    java.util.HashSet<Integer> seen = new java.util.HashSet<>();
    java.util.HashSet<Integer> duplicates = new java.util.HashSet<>();
    for (int num : nums) {
        if (!seen.add(num)) {
            duplicates.add(num);
        }
    }
    int sum = 0;
    for (int num : seen) {
        if (!duplicates.contains(num)) {
            sum += num;
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        int min = Integer.MAX_VALUE;
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            if (dp[i - square] + 1 < min) {
                min = dp[i - square] + 1;
            }
        }
        dp[i] = min;
    }
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }
    StringBuilder result = new StringBuilder();
    StringBuilder word = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == ' ') {
            result.append(word.reverse());
            result.append(' ');
            word.setLength(0);
        } else {
            word.append(c);
        }
    }
    result.append(word.reverse());
    return result.toString();
}
